// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccessLog List the dashboard access log, newest first
	// (GET /access-log)
	ListAccessLog(ctx context.Context, request ListAccessLogRequestObject) (ListAccessLogResponseObject, error)
	// SetPasswordFromAccessLink Set a password with a single-use access link
	// (POST /auth/access-link)
	SetPasswordFromAccessLink(ctx context.Context, request SetPasswordFromAccessLinkRequestObject) (SetPasswordFromAccessLinkResponseObject, error)
	// ReportActivity Report an operator gesture
	// (POST /auth/activity)
	ReportActivity(ctx context.Context, request ReportActivityRequestObject) (ReportActivityResponseObject, error)
	// Login First factor, email and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Close the session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Me The signed-in operator and what they may do
	// (GET /auth/me)
	Me(ctx context.Context, request MeRequestObject) (MeResponseObject, error)
	// ConfirmTotp Confirm a pending authenticator app
	// (POST /auth/mfa/totp/confirm)
	ConfirmTotp(ctx context.Context, request ConfirmTotpRequestObject) (ConfirmTotpResponseObject, error)
	// EnrollTotp Enrol an authenticator app
	// (POST /auth/mfa/totp/enroll)
	EnrollTotp(ctx context.Context, request EnrollTotpRequestObject) (EnrollTotpResponseObject, error)
	// VerifyMfa Second factor, TOTP code, recovery code or passkey assertion
	// (POST /auth/mfa/verify)
	VerifyMfa(ctx context.Context, request VerifyMfaRequestObject) (VerifyMfaResponseObject, error)
	// BeginWebauthnAssertion Open a passkey assertion
	// (POST /auth/mfa/webauthn/assert/begin)
	BeginWebauthnAssertion(ctx context.Context, request BeginWebauthnAssertionRequestObject) (BeginWebauthnAssertionResponseObject, error)
	// ListWebauthnPasskeys The passkeys of the signed-in operator
	// (GET /auth/mfa/webauthn/passkeys)
	ListWebauthnPasskeys(ctx context.Context, request ListWebauthnPasskeysRequestObject) (ListWebauthnPasskeysResponseObject, error)
	// DeleteWebauthnPasskey Remove one of one's passkeys
	// (DELETE /auth/mfa/webauthn/passkeys/{passkeyId})
	DeleteWebauthnPasskey(ctx context.Context, request DeleteWebauthnPasskeyRequestObject) (DeleteWebauthnPasskeyResponseObject, error)
	// BeginWebauthnRegistration Open a passkey registration
	// (POST /auth/mfa/webauthn/register/begin)
	BeginWebauthnRegistration(ctx context.Context, request BeginWebauthnRegistrationRequestObject) (BeginWebauthnRegistrationResponseObject, error)
	// FinishWebauthnRegistration Register the passkey the device produced
	// (POST /auth/mfa/webauthn/register/finish)
	FinishWebauthnRegistration(ctx context.Context, request FinishWebauthnRegistrationRequestObject) (FinishWebauthnRegistrationResponseObject, error)
	// Health Liveness probe
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// ListOperators List operators, their roles and second-factor state
	// (GET /operators)
	ListOperators(ctx context.Context, request ListOperatorsRequestObject) (ListOperatorsResponseObject, error)
	// CreateOperator Create an operator, without role or password
	// (POST /operators)
	CreateOperator(ctx context.Context, request CreateOperatorRequestObject) (CreateOperatorResponseObject, error)
	// UpdateOperator Disable or re-enable an operator
	// (PATCH /operators/{operatorId})
	UpdateOperator(ctx context.Context, request UpdateOperatorRequestObject) (UpdateOperatorResponseObject, error)
	// RequestOperatorAccessLink Send a single-use access link
	// (POST /operators/{operatorId}/access-link)
	RequestOperatorAccessLink(ctx context.Context, request RequestOperatorAccessLinkRequestObject) (RequestOperatorAccessLinkResponseObject, error)
	// SetOperatorRoles Replace an operator's roles
	// (PUT /operators/{operatorId}/roles)
	SetOperatorRoles(ctx context.Context, request SetOperatorRolesRequestObject) (SetOperatorRolesResponseObject, error)
	// ListRoles List roles, their permissions and holders
	// (GET /roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// CreateRole Compose a custom role
	// (POST /roles)
	CreateRole(ctx context.Context, request CreateRoleRequestObject) (CreateRoleResponseObject, error)
	// DeleteRole Delete a custom role nobody holds
	// (DELETE /roles/{roleId})
	DeleteRole(ctx context.Context, request DeleteRoleRequestObject) (DeleteRoleResponseObject, error)
	// UpdateRole Replace a custom role's description and permissions
	// (PATCH /roles/{roleId})
	UpdateRole(ctx context.Context, request UpdateRoleRequestObject) (UpdateRoleResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

